mapper.select:
/* ScheduleGuardMapper.selectLeaveLockedDays */ SELECT D.WORK_YMD AS WORK_YMD , MIN(CASE WHEN U.USE_UNIT_TYPE = '00' THEN '00' ELSE U.USE_UNIT_TYPE END) AS USE_UNIT_TYPE FROM (
SELECT #{ymd} AS WORK_YMD
) D INNER JOIN TB_USER_LEAVE_USE U ON U.CMPNY_CD = #{cmpnyCd} AND U.USER_CD = #{userCd} AND U.LEAVE_STATUS = 'CONFIRMED' AND U.DEL_YN = 'N' AND U.START_DATE <= D.WORK_YMD AND U.END_DATE >= D.WORK_YMD GROUP BY D.WORK_YMD

/* ScheduleGuardMapper.selectOvertimeLockedDays */
SELECT D.WORK_YMD
  FROM (

            SELECT #{ymd} AS WORK_YMD

       ) D
 WHERE EXISTS (
        SELECT 1
          FROM TB_USER_OVERTIME_MGMT OM
         WHERE OM.CMPNY_CD = #{cmpnyCd}
           AND OM.SITE_CD  = #{siteCd}
           AND OM.USER_CD  = #{userCd}
           AND OM.WORK_YMD = D.WORK_YMD
           AND OM.DEL_YN   = 'N'
           AND OM.OT_STATUS  <>  'CANCELLED'
       )
    OR EXISTS (
        SELECT 1
          FROM TB_USER_ATTD_REQ RQ
         WHERE RQ.CMPNY_CD = #{cmpnyCd}
           AND RQ.SITE_CD  = #{siteCd}
           AND RQ.USER_CD  = #{userCd}
           AND RQ.WORK_YMD = D.WORK_YMD
           AND RQ.DEL_YN   = 'N'
           AND RQ.REQ_TYPE IN ('03', '04')
           AND RQ.REQ_STATUS IN ('01', '02')
       )

/* ScheduleGuardMapper.selectEffectiveSchWindow */
SELECT E.FST_SCH_STR_TIME AS fstStart
     , E.FST_SCH_END_TIME AS fstEnd
     , E.SEC_SCH_STR_TIME AS secStart
     , E.SEC_SCH_END_TIME AS secEnd
  FROM (
        /* 현재본 (HIST_IDX 최댓값으로 두어 동일 APPLY_DATE 중복 시 현재본 우선) */
        SELECT M.SCH_CD, M.APPLY_DATE
             , M.FST_SCH_STR_TIME, M.FST_SCH_END_TIME, M.SEC_SCH_STR_TIME, M.SEC_SCH_END_TIME
             , 2147483647 AS HIST_IDX
          FROM TB_SCH_MGMT M
         WHERE M.CMPNY_CD = #{cmpnyCd}
           AND M.SITE_CD  = #{siteCd}
           AND M.SCH_CD   = #{schCd}
        UNION ALL
        /* 이력본 */
        SELECT H.SCH_CD, H.APPLY_DATE
             , H.FST_SCH_STR_TIME, H.FST_SCH_END_TIME, H.SEC_SCH_STR_TIME, H.SEC_SCH_END_TIME
             , H.HIST_IDX
          FROM TB_SCH_MGMT_HIST H
         WHERE H.CMPNY_CD = #{cmpnyCd}
           AND H.SITE_CD  = #{siteCd}
           AND H.SCH_CD   = #{schCd}
       ) E
 WHERE E.APPLY_DATE  <=  #{asOfYmd}
   AND E.HIST_IDX = (
        SELECT MAX(E2.HIST_IDX)
          FROM (
                SELECT M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX
                  FROM TB_SCH_MGMT M2
                 WHERE M2.CMPNY_CD = #{cmpnyCd} AND M2.SITE_CD = #{siteCd} AND M2.SCH_CD = #{schCd}
                UNION ALL
                SELECT H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX
                  FROM TB_SCH_MGMT_HIST H2
                 WHERE H2.CMPNY_CD = #{cmpnyCd} AND H2.SITE_CD = #{siteCd} AND H2.SCH_CD = #{schCd}
               ) E2
         WHERE E2.SCH_CD     = E.SCH_CD
           AND E2.APPLY_DATE = E.APPLY_DATE
       )
 ORDER BY E.APPLY_DATE DESC
 LIMIT 1

/* ScheduleGuardMapper.selectUserWorkPlanCd */
SELECT WP.WORK_PLAN_CD
  FROM TB_USER_WORK_PLAN WP
 WHERE WP.CMPNY_CD = #{cmpnyCd}
   AND WP.SITE_CD  = #{siteCd}
   AND WP.USER_CD  = #{userCd}
   AND WP.WORK_YMD = #{workYmd}
 LIMIT 1
